begin;
create or replace function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end;$$;
do $$
declare org uuid:=gen_random_uuid();actor uuid:='99999999-9999-4999-8999-999999999902';conversation uuid:=gen_random_uuid();brief uuid:=gen_random_uuid();version uuid:=gen_random_uuid();connection uuid:=gen_random_uuid();op uuid:=gen_random_uuid();request jsonb;prepared jsonb;quote jsonb;rate jsonb;acceptance jsonb;job jsonb;again jsonb;manifest jsonb;source jsonb;video_request jsonb;total bigint;
begin
 insert into public.organizations(id,name,slug) values(org,'Transactional Design media QA','design-media-qa-'||org::text);
 insert into public.organization_memberships(organization_id,user_id,role,department_id,status) values(org,actor,'operations_admin','design','active');
 insert into public.department_chat_conversations(id,organization_id,department_id,owner_id,title,context_kind) values(conversation,org,'design',actor,'Rollback media QA','department_private');
 insert into public.design_creative_briefs(id,organization_id,visibility,created_by,updated_by) values(brief,org,'private',actor,actor);
 insert into public.design_creative_brief_versions(id,organization_id,creative_brief_id,version_number,content,content_checksum,validation_snapshot,operation_key,created_by) values(version,org,brief,1,'{"title":"Synthetic","purpose":"Test","instructions":"Synthetic local-only image","audience":"QA"}',repeat('a',64),'{"valid":true}',gen_random_uuid(),actor);
 update public.design_creative_briefs set current_version_id=version,frozen_version_id=version,revision=2 where id=brief;
 insert into public.integration_connections(id,organization_id,provider,display_name,secret_name,status,created_by) values(connection,org,'higgsfield','Rollback no-credential fixture','ANKA_HIGGSFIELD_LOCAL_QA_NO_CREDENTIAL','verified',actor);
 insert into private.ai_execution_budget_limits(organization_id,monthly_limit_microusd,spend_guard_mode) values(org,null,'provider_managed');
 request:=jsonb_build_object('organization_id',org,'context',jsonb_build_object('kind','private','id',conversation),'creative_brief_version_id',version,'connector_connection_id',connection,'provider','higgsfield','model_id','higgsfield-ai/soul/v2/standard','settings','{"resolution":"720p","aspect_ratio":"16:9","enhance_prompt":false}'::jsonb,'output_count',1,'input_versions','[]'::jsonb,'prompt_checksum',repeat('0',64));
 prepared:=public.prepare_design_media_request(org,actor,request);request:=prepared->'request';
 perform pg_temp.ok(request->>'prompt_checksum'=encode(sha256(convert_to(prepared->>'prompt','UTF8')),'hex'),'database derives exact confirmed prompt');

 rate:=public.configure_design_media_reference_rate(org,actor,'higgsfield',request->>'model_id',request->'settings',3000000,'https://open.higgsfield.ai/pricing#synthetic-only',clock_timestamp(),clock_timestamp()+interval '1 hour');
 perform pg_temp.ok(rate->>'price_basis'='estimated','reference rate is not verified');
 quote:=public.quote_design_media_request(org,actor,request);
 perform pg_temp.ok(quote->>'price_basis'='estimated' and quote->>'verified_at' is null and quote->>'reviewed_at' is not null,'quote explicitly estimate, no verified timestamp');
 acceptance:=jsonb_build_object('generate',true,'quote_id',quote->>'id','request_checksum',quote->>'request_checksum','total_max_charge_microusd',3000000,'confirm_above_threshold',true);
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance||'{"accept_estimated_price_risk":true}'::jsonb);raise exception 'FAIL un-enrolled estimate';exception when insufficient_privilege then raise notice 'PASS estimates cannot bypass shared enrollment';end;
 insert into private.design_media_test_budgets(organization_id) values(org);
 begin perform public.set_design_estimated_test_mode(org,actor,true,false,clock_timestamp()+interval '1 hour');raise exception 'FAIL absent risk';exception when invalid_parameter_value then raise notice 'PASS absent risk denied';end;
 begin perform public.set_design_estimated_test_mode(org,actor,true,true,clock_timestamp()+interval '25 hours');raise exception 'FAIL duration';exception when invalid_parameter_value then raise notice 'PASS mode expiry bound';end;
 update public.organization_memberships set role='executive' where organization_id=org and user_id=actor;
 begin perform public.set_design_estimated_test_mode(org,actor,true,true,clock_timestamp()+interval '1 hour');raise exception 'FAIL role';exception when insufficient_privilege then raise notice 'PASS non-admin denied';end;
 update public.organization_memberships set role='operations_admin' where organization_id=org and user_id=actor;
 perform public.set_design_estimated_test_mode(org,actor,true,true,clock_timestamp()+interval '1 hour');
 perform pg_temp.ok((select state='estimated' and evidence_reference is null and verified_at is null from private.design_media_test_budgets where organization_id=org),'activation not mislabeled verified');
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL per-request risk';exception when insufficient_privilege then raise notice 'PASS per-request risk required';end;
 acceptance:=acceptance||'{"accept_estimated_price_risk":true}'::jsonb;
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance-'confirm_above_threshold');raise exception 'FAIL threshold';exception when insufficient_privilege then raise notice 'PASS above USD2 confirmation retained';end;
 job:=public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);
 again:=public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);
 perform pg_temp.ok((again->>'must_not_submit')::boolean,'estimated replay no dispatch');
 perform pg_temp.ok((select consumed_microusd=3000000 and overage_microusd=0 from private.design_media_test_budgets where organization_id=org),'one estimated reservation');
 perform public.record_design_media_generation(org,actor,(job->>'id')::uuid,(job->>'claim_id')::uuid,'outcome_unknown',null);
 perform pg_temp.ok((select consumed_microusd=3000000 from private.design_media_test_budgets where organization_id=org),'unknown reservation retained');
 perform public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,7000000,'synthetic provider billing evidence');
 perform pg_temp.ok((select actual_cost_microusd=7000000 and max_cost_microusd=3000000 and status='settled' from private.ai_execution_budget_reservations where design_media_job_id=(job->>'id')::uuid),'actual overage recorded without rewriting estimate');
 perform pg_temp.ok((select consumed_microusd=3000000 and overage_microusd=4000000 from private.design_media_test_budgets where organization_id=org),'actual overage counts once');
 again:=public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,7000000,'synthetic provider billing evidence');
 perform pg_temp.ok((again->>'idempotent_replay')::boolean and (select overage_microusd=4000000 from private.design_media_test_budgets where organization_id=org),'billing replay no duplicate overage');
 begin perform public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,1,'changed evidence');raise exception 'FAIL conflicting reconcile';exception when unique_violation then raise notice 'PASS conflicting reconciliation denied';end;
 op:=gen_random_uuid();job:=public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);
 perform pg_temp.ok((select consumed_microusd+overage_microusd=10000000 from private.design_media_test_budgets where organization_id=org),'exact shared allowance reachable');
 begin perform public.claim_design_media_generation(org,actor,gen_random_uuid(),(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL exceeded allowance';exception when numeric_value_out_of_range then raise notice 'PASS aggregate allowance blocks new request';end;
 perform public.record_design_media_generation(org,actor,(job->>'id')::uuid,(job->>'claim_id')::uuid,'outcome_unknown',null);
 perform public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,0,'synthetic zero charge evidence');
 perform pg_temp.ok((select consumed_microusd+overage_microusd=10000000 from private.design_media_test_budgets where organization_id=org),'lower actual does not refill one-time allowance');
 begin update private.design_media_test_budgets set overage_microusd=0 where organization_id=org;raise exception 'FAIL overage reset';exception when insufficient_privilege then raise notice 'PASS overage cannot decrease';end;
 perform public.set_design_estimated_test_mode(org,actor,false,false,null);
 perform public.set_design_estimated_test_mode(org,actor,true,true,clock_timestamp()+interval '1 hour');
 perform pg_temp.ok((select consumed_microusd+overage_microusd=10000000 from private.design_media_test_budgets where organization_id=org),'disable and reenabling does not reset');
 update private.design_media_test_budgets set estimated_valid_until=clock_timestamp()-interval '1 second',estimated_risk_accepted_at=clock_timestamp()-interval '1 hour' where organization_id=org;
 begin perform public.claim_design_media_generation(org,actor,gen_random_uuid(),(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL expired mode';exception when insufficient_privilege then raise notice 'PASS expired mode blocks';end;
 perform pg_temp.ok(not has_function_privilege('authenticated','public.set_design_estimated_test_mode(uuid,uuid,boolean,boolean,timestamptz)','EXECUTE') and not has_function_privilege('anon','public.configure_design_media_reference_rate(uuid,uuid,text,text,jsonb,bigint,text,timestamptz,timestamptz)','EXECUTE'),'new entry points service only');
 perform pg_temp.ok(not has_table_privilege('service_role','private.design_media_test_budgets','UPDATE,INSERT,DELETE,SELECT'),'closed budget table rights retained');
end;$$;
rollback;
